    "\n",
    "plt.tight_layout()\n",
    "\n",
    "\n",
    "\n",
    "# Save figures\n",
    "\n",
    "save_png = r\"D:\\FabI\\PCA\\Kmeans_Elbow_Silhouette.png\"\n",
    "\n",
