    "\n",
    "\n",
    "\n",
    "total = 0\n",
    "\n",
    "\n",
    "\n",
    "# Generate complexes\n",
    "\n",
    "for ligand_file in glob.glob(\n",
    "    os.path.join(\n",
    "        ligand_dir,\n",
    "        \"*.pdbqt\"\n",
    "    )\n",
    "):\n",
    "\n",
    "\n",
