    "\n",
    "\n",
    "\n",
    "    with open(\n",
    "        complex_file,\n",
    "        \"w\"\n",
    "    ) as f:\n",
    "\n",
    "        f.write(\n",
    "            protein_data\n",
    "        )\n",
    "\n",
    "        f.write(\n",
    "            ligand_data\n",
    "        )\n",
    "\n",
    "\n",
